Emulator.AutoHotkeyScript:
; =====================================================
; Middle Mouse Button behavior:
;   • Single click  → Esc → Ctrl+Alt+F4 → Shift+C
;   • Double click  → Esc  + close active window + close extra executables
;   • Long press ≥2 s → Esc  + close active window + close extra executables
; =====================================================

; ---------- Config ----------
DoubleClickInterval := 250    ; ms window for double-click
SingleDelay         := 200    ; ms delay before single action triggers
LongPressDuration   := 2000   ; hold time (ms) for long-press Escape
CloseActiveOnExit   := true   ; also close the currently focused app on double/long
GracefulWaitMS      := 700    ; wait after WinClose before checking/forcing
KillIfNeeded        := true   ; force close if graceful close fails

; Add any extra executables you want closed (names as seen in Task Manager)
; Examples: "obs64.exe", "kdenlive.exe", "superf4.exe"
ExtraExecutables := ["bms_GGG.exe", "Game Loader All RH.exe", "otomedius.exe", "spice.exe"]


; ---------- Hotkeys ----------
$MButton::
    PressTime := A_TickCount
    SetTimer, __CheckLongPress, 50

    if (A_PriorHotkey = "$MButton" && A_TimeSincePriorHotkey < DoubleClickInterval) {
        SetTimer, __DoSingleMButton, Off
        SetTimer, __CheckLongPress, Off
        Send, {Esc}
        __CloseTargets("double-click")
        return
    }

    SetTimer, __DoSingleMButton, % -SingleDelay
return

$MButton Up::
    SetTimer, __CheckLongPress, Off
return


; ---------- Single-click action ----------
__DoSingleMButton:
    if (A_TickCount - PressTime < LongPressDuration) {
        Send, !{F4}
        Sleep, 50
        ;Send, ^!{F4}
        ;Sleep, 50
        ;Send, +c
    }
return


; ---------- Long-press detection ----------
__CheckLongPress:
    if GetKeyState("MButton", "P") {
        if (A_TickCount - PressTime >= LongPressDuration) {
            SetTimer, __DoSingleMButton, Off
            SetTimer, __CheckLongPress, Off
            Send, {Esc}
            __CloseTargets("long-press")
        }
    } else {
        SetTimer, __CheckLongPress, Off
    }
return


; =====================================================
; Helpers: Close active window + listed executables
; =====================================================
__CloseTargets(reason := "") {
    global CloseActiveOnExit, ExtraExecutables
    if (CloseActiveOnExit)
        __CloseActiveWindow()

    for each, exe in ExtraExecutables
        __CloseExeGracefully(exe)
}

__CloseActiveWindow() {
    global GracefulWaitMS, KillIfNeeded
    DetectHiddenWindows, On
    WinGet, hWnd, ID, A
    if (hWnd) {
        WinClose, ahk_id %hWnd%
        WinWaitClose, ahk_id %hWnd%,, % (GracefulWaitMS/1000)
        ; If it didn’t close, try to find its process and kill it (optional)
        if (KillIfNeeded && WinExist("ahk_id " . hWnd)) {
            WinGet, pid, PID, ahk_id %hWnd%
            if (pid)
                Process, Close, %pid%
        }
    }
}

__CloseExeGracefully(exeName) {
    global GracefulWaitMS, KillIfNeeded
    if (!exeName)
        return

    DetectHiddenWindows, On
    SetTitleMatchMode, 2

    ; Close all top-level windows owned by this exe
    WinGet, winList, List, ahk_exe %exeName%
    Loop, %winList%
    {
        thisID := winList%A_Index%
        WinClose, ahk_id %thisID%
    }

    ; Give it a moment to exit on its own
    Sleep, %GracefulWaitMS%

    ; If any instance is still running, optionally force close
    Process, Exist, %exeName%
    pid := ErrorLevel
    While (pid) {
        if (KillIfNeeded)
            Process, Close, %pid%
        ; Check again (in case of multiple instances)
        Process, Exist, %exeName%
        pid := ErrorLevel
    }
}

